package org.apache.lucene.facet;

import java.io.IOException;
import org.apache.lucene.internal.hppc.IntIntHashMap;
import org.apache.lucene.util.BytesRef;

/** Keeps highest results, first by largest int value, then tie-break by smallest ord. */
public class TopOrdAndIntQueue extends TopOrdAndNumberQueue {

  private int bottomCount;
  private int bottomOrd = Integer.MAX_VALUE;

  /** Sole constructor. */
  public TopOrdAndIntQueue(int topN) {
    super(topN);
  }

  /** Holds an ordinal and an int value. */
  public static final class OrdAndInt extends OrdAndValue {
    /** The value corresponding to the ordinal is an int. */
    public int value;

    /** Default constructor. */
    public OrdAndInt() {}

    @Override
    public boolean lessThan(OrdAndValue other) {
      OrdAndInt otherOrdAndInt = (OrdAndInt) other;
      if (value < otherOrdAndInt.value) {
        return true;
      }
      if (value > otherOrdAndInt.value) {
        return false;
      }
      return ord > otherOrdAndInt.ord;
    }

    @Override
    public Number getValue() {
      return value;
    }
  }

  @Override
  public OrdAndValue newOrdAndValue() {
    return new OrdAndInt();
  }

  FacetResult getTopChildren(StringValueFacetCounts counts, int topN, String dim, String... path)
      throws IOException {
    counts.validateDimAndPathForGetChildren(dim, path);

    OrdAndInt reuse = null;
    int childCount = 0; // total number of labels with non-zero count

    if (counts.sparseCounts != null) {
      for (IntIntHashMap.IntIntCursor sparseCount : counts.sparseCounts) {
        childCount++; // every count in sparseValues should be non-zero
        int ord = sparseCount.key;
        int count = sparseCount.value;
        if (count > bottomCount || (count == bottomCount && ord < bottomOrd)) {
          if (reuse == null) {
            reuse = (OrdAndInt) newOrdAndValue();
          }
          reuse.ord = ord;
          reuse.value = count;
          reuse = (OrdAndInt) insertWithOverflow(reuse);
          if (size() == topN) {
            bottomCount = ((OrdAndInt) top()).value;
            bottomOrd = top().ord;
          }
        }
      }
    } else {
      for (int i = 0; i < counts.denseCounts.length; i++) {
        int count = counts.denseCounts[i];
        if (count != 0) {
          childCount++;
          if (count > bottomCount || (count == bottomCount && i < bottomOrd)) {
            if (reuse == null) {
              reuse = (OrdAndInt) newOrdAndValue();
            }
            reuse.ord = i;
            reuse.value = count;
            reuse = (OrdAndInt) insertWithOverflow(reuse);
            if (size() == topN) {
              bottomCount = ((OrdAndInt) top()).value;
              bottomOrd = top().ord;
            }
          }
        }
      }
    }

    int resultCount = size();
    LabelAndValue[] labelValues = new LabelAndValue[resultCount];
    for (int i = labelValues.length - 1; i >= 0; i--) {
      OrdAndInt ordAndValue = (OrdAndInt) pop();
      final BytesRef term = counts.docValues.lookupOrd(ordAndValue.ord);
      labelValues[i] = new LabelAndValue(term.utf8ToString(), ordAndValue.value);
    }

    return new FacetResult(
        counts.field, new String[0], counts.totalDocCount, labelValues, childCount);
  }
}

